create table if not exists maintenance_members(user_id uuid not null references auth.users(id)on delete cascade,organization_id uuid not null references organizations(id),role text not null check(role in('admin','maintenance','supervisor','operator','viewer')),active boolean not null default true,created_at timestamptz not null default now(),primary key(user_id,organization_id));
insert into maintenance_members(user_id,organization_id,role)select u.id,o.id,'admin'from auth.users u cross join lateral(select id from organizations order by created_at limit 1)o on conflict do nothing;
create table if not exists maintenance_audit_log(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id),user_id uuid,entity_type text not null,entity_id uuid,action text not null,old_values jsonb,new_values jsonb,created_at timestamptz not null default now());create index if not exists maintenance_audit_entity_idx on maintenance_audit_log(organization_id,entity_type,entity_id,created_at desc);
alter table maintenance_members enable row level security;alter table maintenance_audit_log enable row level security;revoke all on maintenance_members,maintenance_audit_log from anon,authenticated;grant all on maintenance_members,maintenance_audit_log to service_role;grant select on maintenance_members to authenticated;create policy maintenance_members_self_read on maintenance_members for select to authenticated using(user_id=auth.uid());
create or replace function maintenance_audit_change()returns trigger language plpgsql security definer set search_path=public as $$declare row_data jsonb;org uuid;eid uuid;begin row_data:=case when tg_op='DELETE'then to_jsonb(old)else to_jsonb(new)end;org:=(row_data->>'organization_id')::uuid;eid:=nullif(row_data->>'id','')::uuid;insert into maintenance_audit_log(organization_id,user_id,entity_type,entity_id,action,old_values,new_values)values(org,auth.uid(),tg_table_name,eid,tg_op,case when tg_op in('UPDATE','DELETE')then to_jsonb(old)end,case when tg_op in('INSERT','UPDATE')then to_jsonb(new)end);return case when tg_op='DELETE'then old else new end;end$$;
do $$declare t text;begin foreach t in array array['maintenance_assets','maintenance_work_orders','maintenance_downtime_events','maintenance_preventive_plans','maintenance_inventory_transactions','maintenance_work_order_labor']loop execute format('drop trigger if exists audit_change on %I',t);execute format('create trigger audit_change after insert or update or delete on %I for each row execute function maintenance_audit_change()',t);end loop;end$$;
create index if not exists maintenance_wo_org_status_due_idx on maintenance_work_orders(organization_id,status,due_at);create index if not exists maintenance_asset_org_status_idx on maintenance_assets(organization_id,status)where active;create index if not exists maintenance_downtime_org_started_idx on maintenance_downtime_events(organization_id,started_at desc);
